-- Catálogo documental vigente (V672).
INSERT doc.TipoDocumento(codigo,nombre,descripcion)
SELECT C.codigo,C.nombre,C.descripcion FROM (VALUES
 ('SOLICITUD',N'Solicitud',N'Petición administrativa dirigida al personal'),
 ('MEMORANDO',N'Memorándum',N'Comunicación o instrucción institucional'),
 ('INFORME',N'Informe',N'Resultados, avances o información de trabajo'),
 ('OFICIO',N'Oficio',N'Comunicación formal'),
 ('PERMISO',N'Permiso',N'Solicitud o autorización administrativa'),
 ('CARTA',N'Carta',N'Comunicación escrita'),
 ('OTRO',N'Otro',N'Documento no clasificado')) C(codigo,nombre,descripcion)
WHERE NOT EXISTS(SELECT 1 FROM doc.TipoDocumento T WHERE T.codigo=C.codigo);
GO
